Bash(node --experimental-strip-types --disable-warning=ExperimentalWarning --input-type=module -e "
const { model: M } = await import\('./tools/lib/skillmodel.ts'\);
const R = await import\('./tools/lib/roster.ts'\);
const { eng } = await import\('./tools/lib/engine.ts'\);
const refs = M.referenceBases\(\);
const beat = eng.hitsPerSec\(eng.REFERENCE.line.aspd\);
for \(const build of ['glass','caster']\) {
  const ref = refs[build];
  console.log\('## ' + build + ' — phys ' + Math.round\(ref.phys\) + ' magic ' + Math.round\(ref.magic\) + ' elem ' + Math.round\(ref.elem\) + ' align ' + Math.round\(ref.align\)\);
  const rows = R.byType\('attack'\).map\(s => {
    const r = M.row\(s, { ...ref, level: 20 }\);
    const rate = r.pressesPerSec == null ? beat : r.pressesPerSec;
    const dmg = r.damage || 0;
    return { name: s.name, basis: s.basis, dmg, rate, dps: dmg * rate, aoe: String\(s.targets||'1'\).split\('/'\)[0] > 1 };
  }\).sort\(\(a,b\) => b.dps - a.dps\);
  for \(const x of rows.slice\(0, 12\)\) console.log\(\(x.dps\).toFixed\(0\).padStart\(6\), x.name.padEnd\(16\), x.basis, \(x.rate\).toFixed\(2\) + '/s', x.aoe ? 'AoE' : ''\);
  const m = rows.filter\(x=>x.basis==='magic'\), p = rows.filter\(x=>x.basis==='phys'\);
  const avg = a => a.reduce\(\(t,x\)=>t+x.dps,0\)/a.length;
  console.log\('  avg DPS: phys ' + Math.round\(avg\(p\)\) + ' · magic ' + Math.round\(avg\(m\)\) + ' · ratio ' + \(avg\(p\)/avg\(m\)\).toFixed\(2\)\);
  console.log\(''\);
}
" 2>&1 | tail -45)
